import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testFilterInts() {
        Assert.assertEquals(listOf(1, 3, 5), filterNotNull(listOf(1, null, 3, null, 5)))
    }

    @Test
    fun testFilterStrings() {
        Assert.assertEquals(listOf("Red", "Blue"), filterNotNull(listOf("Red", null, "Blue")))
    }

    @Test
    fun testAllNull() {
        val result: List<Int> = filterNotNull(listOf(null, null, null))
        Assert.assertEquals(emptyList<Int>(), result)
    }

    @Test
    fun testNoNulls() {
        Assert.assertEquals(listOf(4, 2, 1, 5), filterNotNull(listOf(4, 2, 1, 5)))
    }

    @Test
    fun testEmptyList() {
        val result: List<String> = filterNotNull(emptyList())
        Assert.assertEquals(emptyList<String>(), result)
    }
}
